,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2313,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Кругом одни заговорщики. Эти глупцы не понимают важности моего дела и стараются держать меня в постоянном неведении! $B$BНе сочти за оскорбление.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,''),(2314,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Что я делаю? Неужели тебе не дано видеть? Я духовидец, $gгосподин мой:госпожа моя;, я вижу лучшее будущее для всех нас. Точнее говоря, я провидец.$B$BНо есть и те, кто стремится заставить нас увязнуть в вещах пустопорожних. Я сказал ему, что я духовидец, и верховный друид Олений Шлем ответил: \"Ну хорошо, миру нужны и те, кто будет копать канавы\".$B$BПока оковы пустопорожнего не будут удалены от нас, я буду помогать Кругу Кенария, перекладывая эти кучи грязи с места на место.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,''),(2320,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Да, но теперь тебе куда полезнее обратиться к травничеству! Ты будешь выращивать редчайшие растения вместо того, чтобы махать топором или зубрить дурацкие заклинания. С сумой вечного цветения даже последний бездарь что-нибудь да вырастит, а уж опытный специалист добьется фантастических успехов.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2333,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Имей в виду, $gкрасавчик:принцесса;, сейчас у меня нет времени на твои шуточки. Я слежу за тем, чтобы исследования верховного друида проходили по плану. Мне приказано избавляться от любых посторонних, если только они не хотят присоединиться к моему славному Кругу Кенария.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,''),(2353,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Приветствую вас, $gблагородный:благородная:c; |3-6($c). Скромная прислужница Круга Кенария желает вам добра и благополучия.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,''),(2354,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Будь $gосмотрителен:осмотрительна;, |3-6($c). У меня уже наготове заклинание превращения на твое имя…',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2355,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Люблю пироги.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Люблю пироги.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Мама всегда говорила, что нет ничего прекраснее в мире, чем кусок теплого, хрустящего домашнего пирога с вишнями!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Мама всегда говорила, что нет ничего прекраснее в мире, чем кусок теплого, хрустящего домашнего пирога с вишнями!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Пирог вышел отличный, хотите?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Пирог вышел отличный, хотите?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'У вас неудачный день? Попробуйте вишневого пирога!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'У вас неудачный день? Попробуйте вишневого пирога!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Этот вишневый пирог так вкусен, что даже взрослый гном бы прослезился.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Этот вишневый пирог так вкусен, что даже взрослый гном бы прослезился.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Попробуйте этого вишневого пирога – вы сразу улыбнетесь, вот увидите!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Попробуйте этого вишневого пирога – вы сразу улыбнетесь, вот увидите!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Свежий вишневый пирог! Пальчики оближешь!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Свежий вишневый пирог! Пальчики оближешь!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Вишневый пирог – самое вкусное блюдо Азерота!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Вишневый пирог – самое вкусное блюдо Азерота!'),(2393,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'О, если бы тут была ветка дерева, чтобы укрыться за ней. Тогда охранники ни за что бы меня не увидели.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2394,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Тебе придется проявить терпение, $N. Мой робот-шпион сейчас внутри и занят очень щекотливой проблемой. Вернусь через секунду.$B$BО, окажи мне услугу, не дай Лесковару увидеть тебя… мы собираемся напасть на него из засады.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2414,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Суровые времена, правда, $N? Куда не пойдешь, всюду кому-то нужна помощь, и мы с женой не исключение.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2433,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Я это видал своими глазами! Самый большой макура из всех, покрупнее кулака горного великана, забрался прямо наверх одного из двух колоссов. Ума не приложу, как ты сможешь туда залезть… Но у этой зверюги наверняка куча сокровищ.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,''),(2434,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Конечно, $N. По-видимому, тебе можно доверять… Ты заслуживаешь доверия! Я такое за версту чую…$B$BВ общем, вернемся к моим словам. Для изготовления одной порции эликсира Видере нужен один корень вечерника. Добыть остальные ингредиенты будет несложно, а вот с эвокорнем придется повозиться.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2493,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Только глупец станет тревожить меня в моем логове.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2497,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Иди в лавку \"Алхимия и Эликсиры Йелмака\". Это в центре Волока, к западу от гигантского дерева.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Иди в лавку \"Алхимия и Эликсиры Йелмака\". Это в центре Волока, к западу от гигантского дерева.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Зелья и масла – вот чему тебя научит Йелмак, если ты $gдостоин:достойна;. Ищи его лавку в середине Волока.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Зелья и масла – вот чему тебя научит Йелмак, если ты $gдостоин:достойна;. Ищи его лавку в середине Волока.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,''),(2499,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Тебе нужен Сару Холодная Ярость из \"Пылающей наковальни\". Это на Аллее Чести, в конце дороги, идущей справа от Рудника Ржавого каньона.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Тебе нужен Сару Холодная Ярость из \"Пылающей наковальни\". Это на Аллее Чести, в конце дороги, идущей справа от Рудника Ржавого каньона.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Возможно, Сару Холодная Ярость когда-нибудь научит тебя владеть топором не хуже моего. Ищи его в \"Пылающей наковальне\", на Аллее Чести – за Рудником Ржавого каньона и направо от дороги.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Возможно, Сару Холодная Ярость когда-нибудь научит тебя владеть топором не хуже моего. Ищи его в \"Пылающей наковальне\", на Аллее Чести – за Рудником Ржавого каньона и направо от дороги.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,NULL