INSERT INTO `locales_npc_text` VALUES (13069,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Я так больше не могу…$b$bОни убивают тебя, а потом едят! И это если повезет!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Я так больше не могу…$b$bОни убивают тебя, а потом едят! И это если повезет!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Ты $gдолжен:должна; помочь мне выбраться отсюда, |3-6($r)!$b$bЯ не хочу стать таким, как они!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Ты $gдолжен:должна; помочь мне выбраться отсюда, |3-6($r)!$b$bЯ не хочу стать такой, как они!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Я не могу ни есть, ни спать с тех пор, как попал сюда.$b$bЯ же не просто отрезанный ломоть для Авангарда…',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Я не могу ни есть, ни спать с тех пор, как попала сюда.$b$bЯ же не просто отрезанный ломоть для Авангарда…',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<хнык> Мой дядя служил в Серебряном Рассвете.$b$bКак у него получалось противостоять этим злобным тварям?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'<хнык> Мой дядя служил в Серебряном Рассвете.$b$bКак у него получалось противостоять этим злобным тварям?',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Каждый раз, когда я закрываю глаза, я вижу, как силы Плети окружают меня!$b$bМне нужно выбраться отсюда…',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Каждый раз, когда я закрываю глаза, я вижу, как силы Плети окружают меня!$b$bМне нужно выбраться отсюда…',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Я здесь умру… я это просто знаю.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Я здесь умру… я просто знаю это.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Мы обреченыыыы!!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Мы обреченыыыы!!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Выбирайся отсюда, пока можешь, |3-6($c)!$b$bНам ни за что не победить…',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Выбирайся отсюда, пока можешь, |3-6($c)!$b$bНам ни за что не победить…'),(13077,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'БУМ!$b$bЭто последнее, что я помню…',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NUL